const STORAGE_KEY = "kuechenplan-prototyp-v1";
const dayNames = ["Montag", "Dienstag", "Mittwoch", "Donnerstag", "Freitag"];
const dayShort = ["MO", "DI", "MI", "DO", "FR"];
const categories = ["Gemüse", "Kühlung", "Fleisch", "Trockenwaren", "Sonstiges"];
const sampleRecipes = [
  { id:"kartoffel", name:"Kartoffel-Spinat-Auflauf", side:"Apfel", allergens:"G", basePortions:10, ingredients:[{name:"Kartoffeln",amount:2.2,unit:"kg",category:"Gemüse"},{name:"Spinat",amount:1,unit:"kg",category:"Gemüse"},{name:"Sahne",amount:.5,unit:"l",category:"Kühlung"},{name:"Käse",amount:350,unit:"g",category:"Kühlung"},{name:"Äpfel",amount:10,unit:"Stk.",category:"Gemüse"}]},
  { id:"linsen", name:"Linseneintopf mit Spätzle", side:"Joghurt", allergens:"A1, C, G", basePortions:10, ingredients:[{name:"Linsen",amount:900,unit:"g",category:"Trockenwaren"},{name:"Suppengemüse",amount:1.2,unit:"kg",category:"Gemüse"},{name:"Spätzle",amount:1.1,unit:"kg",category:"Trockenwaren"},{name:"Joghurt",amount:10,unit:"Stk.",category:"Kühlung"}]},
  { id:"maultaschen", name:"Überbackene Maultaschen", side:"Tomatensoße und Gurkensalat", allergens:"A1, C, G", basePortions:10, ingredients:[{name:"Maultaschen",amount:2,unit:"kg",category:"Kühlung"},{name:"Tomatensoße",amount:1.5,unit:"l",category:"Trockenwaren"},{name:"Käse",amount:300,unit:"g",category:"Kühlung"},{name:"Gurken",amount:4,unit:"Stk.",category:"Gemüse"}]},
  { id:"pute", name:"Putengeschnetzeltes", side:"Reis und Salat", allergens:"G", basePortions:10, ingredients:[{name:"Putenfleisch",amount:1.4,unit:"kg",category:"Fleisch"},{name:"Reis",amount:800,unit:"g",category:"Trockenwaren"},{name:"Sahne",amount:.5,unit:"l",category:"Kühlung"},{name:"Blattsalat",amount:3,unit:"Stk.",category:"Gemüse"}]},
  { id:"kuerbis", name:"Kürbiscremesuppe", side:"Brot", allergens:"A1, G", basePortions:10, ingredients:[{name:"Hokkaido-Kürbis",amount:2.5,unit:"kg",category:"Gemüse"},{name:"Kartoffeln",amount:.8,unit:"kg",category:"Gemüse"},{name:"Sahne",amount:.4,unit:"l",category:"Kühlung"},{name:"Brot",amount:2,unit:"Packung",category:"Trockenwaren"}]},
  { id:"milchreis", name:"Milchreis", side:"Apfelmus", allergens:"G", basePortions:10, ingredients:[{name:"Milchreis",amount:750,unit:"g",category:"Trockenwaren"},{name:"Milch",amount:3.5,unit:"l",category:"Kühlung"},{name:"Apfelmus",amount:2,unit:"Packung",category:"Trockenwaren"}]},
  { id:"fisch", name:"Seelachsfilet", side:"Kartoffeln und Gemüse", allergens:"D, G", basePortions:10, ingredients:[{name:"Seelachsfilet",amount:1.4,unit:"kg",category:"Fleisch"},{name:"Kartoffeln",amount:2,unit:"kg",category:"Gemüse"},{name:"Mischgemüse",amount:1.2,unit:"kg",category:"Gemüse"}]},
  { id:"nudeln", name:"Nudeln mit Tomatensoße", side:"Rohkost", allergens:"A1", basePortions:10, ingredients:[{name:"Nudeln",amount:1.1,unit:"kg",category:"Trockenwaren"},{name:"Tomatensoße",amount:1.8,unit:"l",category:"Trockenwaren"},{name:"Karotten",amount:1.2,unit:"kg",category:"Gemüse"}]}
];
function initialState(){return{weekStart:"2026-09-14",portions:37,recipes:sampleRecipes,plan:["kartoffel","linsen","maultaschen","pute","kuerbis"],checked:[],stockNotes:""};}
function loadState(){try{const saved=JSON.parse(localStorage.getItem(STORAGE_KEY));return saved&&saved.recipes?saved:initialState();}catch{return initialState();}}
let state=loadState(),selectedDay=null,deferredInstall; const $=(s,r=document)=>r.querySelector(s), $$=(s,r=document)=>[...r.querySelectorAll(s)];
function save(){localStorage.setItem(STORAGE_KEY,JSON.stringify(state));}
function dateAt(i){const d=new Date(state.weekStart+"T12:00:00");d.setDate(d.getDate()+i);return d;}
function dateShort(d){return new Intl.DateTimeFormat("de-DE",{day:"2-digit",month:"2-digit"}).format(d);}
function weekText(){const a=dateAt(0),b=dateAt(4),year=b.getFullYear(),month=new Intl.DateTimeFormat("de-DE",{month:"long"}).format(b);return a.getMonth()===b.getMonth()?`${a.getDate()}. - ${b.getDate()}. ${month} ${year}`:`${dateShort(a)} - ${dateShort(b)} ${year}`;}
function recipe(id){return state.recipes.find(r=>r.id===id);} function formatAmount(n){return new Intl.NumberFormat("de-DE",{maximumFractionDigits:2}).format(Math.round(n*100)/100);}
function normalizeAmount(amount,unit){if(unit==="g"&&amount>=1000)return{amount:amount/1000,unit:"kg"};if(unit==="ml"&&amount>=1000)return{amount:amount/1000,unit:"l"};return{amount,unit};}
function toast(message){const el=$("#toast");el.textContent=message;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2200);}
function renderPlan(){$("#week-label").textContent=weekText();$("#portions").value=state.portions;$("#day-list").innerHTML=dayNames.map((day,i)=>{const r=recipe(state.plan[i]);return `<article class="day-card"><div class="day-date"><strong>${dayShort[i]}</strong><span>${dateShort(dateAt(i))}</span></div><button class="meal-select" data-day="${i}"><span>${r?r.name:"Gericht auswählen"}</span><small>${r?[r.side,r.allergens&&`Allergene: ${r.allergens}`].filter(Boolean).join(" · "):"Tippen zum Auswählen"}</small></button></article>`;}).join("");}
function renderRecipes(filter=""){const q=filter.trim().toLowerCase(),items=state.recipes.filter(r=>(r.name+" "+r.side).toLowerCase().includes(q));$("#recipe-list").innerHTML=items.length?items.map(r=>`<article class="recipe-card"><div class="recipe-letter">${r.name[0]}</div><div><h3>${r.name}</h3><p>${r.side||"Ohne Beilage"}</p><small>${r.ingredients.length} Zutaten · für ${r.basePortions} Kinder${r.allergens?` · ${r.allergens}`:""}</small></div></article>`).join(""):`<div class="empty-state"><strong>Kein Rezept gefunden</strong><span>Versuchen Sie einen anderen Suchbegriff.</span></div>`;}
function shoppingItems(){const map=new Map();state.plan.map(recipe).filter(Boolean).forEach(r=>r.ingredients.forEach(x=>{const key=(x.name+"|"+x.unit).toLowerCase(),current=map.get(key)||{...x,amount:0};current.amount+=x.amount*(state.portions/r.basePortions);map.set(key,current);}));return[...map.values()].map(x=>({...x,...normalizeAmount(x.amount,x.unit)})).sort((a,b)=>categories.indexOf(a.category)-categories.indexOf(b.category)||a.name.localeCompare(b.name,"de"));}
function renderShopping(){const items=shoppingItems();$("#shopping-week").textContent=weekText();$("#shopping-summary").innerHTML=`<div><strong>${items.length}</strong><span>Artikel</span></div><div><strong>${state.portions}</strong><span>Kinder</span></div><div><strong>${state.plan.filter(Boolean).length}</strong><span>Gerichte</span></div>`;$("#shopping-list").innerHTML=categories.map(cat=>{const group=items.filter(x=>x.category===cat);if(!group.length)return"";return`<section class="shopping-group"><h3>${cat}</h3>${group.map(x=>{const key=x.name+"|"+x.unit;return`<label class="shopping-row ${state.checked.includes(key)?"checked":""}"><input type="checkbox" data-item="${key}" ${state.checked.includes(key)?"checked":""}><span>${x.name}</span><strong>${formatAmount(x.amount)} ${x.unit}</strong></label>`;}).join("")}</section>`;}).join("");$("#stock-notes").value=state.stockNotes;}
function renderAll(){renderPlan();renderRecipes($("#recipe-search")?.value||"");renderShopping();}
function navigate(name){$$(".screen").forEach(s=>s.classList.toggle("active",s.id===`screen-${name}`));$$(".nav-item").forEach(n=>n.classList.toggle("active",n.dataset.screen===name));window.scrollTo({top:0,behavior:"smooth"});if(name==="shopping")renderShopping();}
function openMealDialog(day){selectedDay=day;$("#meal-dialog-day").textContent=`${dayNames[day]}, ${dateShort(dateAt(day))}`;$("#meal-options").innerHTML=state.recipes.map(r=>`<button class="meal-option ${state.plan[day]===r.id?"selected":""}" data-recipe="${r.id}"><span><strong>${r.name}</strong><small>${r.side||"Ohne Beilage"}${r.allergens?` · ${r.allergens}`:""}</small></span><b>${state.plan[day]===r.id?"✓":"›"}</b></button>`).join("");$("#meal-dialog").showModal();}
function planShareText(){return`Essensplan ${weekText()}\n\n${dayNames.map((d,i)=>{const r=recipe(state.plan[i]);return`${d}: ${r?r.name+(r.side?`, ${r.side}`:""):"-"}`;}).join("\n")}`;}
function printView(type){document.body.dataset.print=type;document.title=type==="plan"?`Essensplan ${weekText()}`:`Einkaufsliste ${weekText()}`;window.print();setTimeout(()=>{delete document.body.dataset.print;document.title="Küchenplan";},500);}
document.addEventListener("click",e=>{const nav=e.target.closest("[data-screen]");if(nav)navigate(nav.dataset.screen);const meal=e.target.closest("[data-day]");if(meal)openMealDialog(Number(meal.dataset.day));const option=e.target.closest("[data-recipe]");if(option){state.plan[selectedDay]=option.dataset.recipe;save();renderAll();$("#meal-dialog").close();toast("Gericht aktualisiert");}const print=e.target.closest("[data-print]");if(print)printView(print.dataset.print);});
$("#portions").addEventListener("change",e=>{state.portions=Math.max(1,Number(e.target.value)||1);save();renderShopping();toast("Mengen neu berechnet");});
$("#previous-week").addEventListener("click",()=>{const d=dateAt(0);d.setDate(d.getDate()-7);state.weekStart=d.toISOString().slice(0,10);save();renderAll();});
$("#next-week").addEventListener("click",()=>{const d=dateAt(0);d.setDate(d.getDate()+7);state.weekStart=d.toISOString().slice(0,10);save();renderAll();});
$("#create-list").addEventListener("click",()=>navigate("shopping")); $("#recipe-search").addEventListener("input",e=>renderRecipes(e.target.value)); $("#add-recipe").addEventListener("click",()=>$("#recipe-dialog").showModal()); $("[data-close-recipe]").addEventListener("click",()=>$("#recipe-dialog").close());
$("#recipe-form").addEventListener("submit",e=>{e.preventDefault();const f=new FormData(e.currentTarget),allowed=["g","kg","ml","l","Stk.","Packung"],ingredients=String(f.get("ingredients")||"").split("\n").map(line=>line.split("|").map(x=>x.trim())).filter(x=>x[0]&&Number(String(x[1]).replace(",","."))).map(x=>({name:x[0],amount:Number(String(x[1]).replace(",",".")),unit:allowed.includes(x[2])?x[2]:"g",category:"Sonstiges"}));state.recipes.push({id:`custom-${Date.now()}`,name:String(f.get("name")),side:String(f.get("side")),basePortions:Number(f.get("basePortions"))||10,allergens:String(f.get("allergens")),ingredients});save();renderAll();e.currentTarget.reset();$("#recipe-dialog").close();toast("Rezept gespeichert");});
$("#shopping-list").addEventListener("change",e=>{if(!e.target.dataset.item)return;state.checked=e.target.checked?[...new Set([...state.checked,e.target.dataset.item])]:state.checked.filter(x=>x!==e.target.dataset.item);save();renderShopping();}); $("#stock-notes").addEventListener("input",e=>{state.stockNotes=e.target.value;save();}); $("#reset-checks").addEventListener("click",()=>{state.checked=[];save();renderShopping();});
$("#share-plan").addEventListener("click",async()=>{const data={title:"Essensplan",text:planShareText()};try{if(navigator.share)await navigator.share(data);else{await navigator.clipboard.writeText(data.text);toast("Essensplan kopiert");}}catch(err){if(err.name!=="AbortError")toast("Teilen ist nicht verfügbar");}});
window.addEventListener("beforeinstallprompt",e=>{e.preventDefault();deferredInstall=e;$("#install-button").classList.remove("hidden");}); $("#install-button").addEventListener("click",async()=>{if(!deferredInstall)return;deferredInstall.prompt();await deferredInstall.userChoice;deferredInstall=null;$("#install-button").classList.add("hidden");});
function registerWebMcp(){const context=document.modelContext;if(!context?.registerTool)return;const controller=new AbortController();Promise.resolve(context.registerTool({name:"set_week_plan",title:"Wochenplan festlegen",description:"Legt Anzahl der Kinder und bis zu fünf Rezept-IDs für den sichtbaren Wochenplan fest.",inputSchema:{type:"object",properties:{portions:{type:"integer",minimum:1,maximum:500},recipeIds:{type:"array",items:{type:"string"},minItems:1,maxItems:5}},required:["portions","recipeIds"],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!Number.isInteger(input?.portions)||input.portions<1||input.portions>500)throw new Error("Ungültige Kinderzahl");if(!Array.isArray(input.recipeIds)||!input.recipeIds.length||input.recipeIds.some(id=>!recipe(id)))throw new Error("Unbekannte Rezept-ID");state.portions=input.portions;state.plan=[...input.recipeIds.slice(0,5),...state.plan.slice(input.recipeIds.length,5)];save();renderAll();return{portions:state.portions,recipeIds:state.plan};}},{signal:controller.signal})).catch(()=>{});}
renderAll();registerWebMcp();if("serviceWorker" in navigator)window.addEventListener("load",()=>navigator.serviceWorker.register("./sw.js"));


